/*
    SpreadsToSinglePages.jsx
    -----------------------------------------------------------
    Converts a spread-based InDesign document into a single-page
    document while preserving:
        • Page size and orientation
        • Margins and column settings
        • Master page assignments (A-Master, B-Master, etc.)
        • Position of all page items
        • Document and master page layouts

    The script duplicates the active document so the original is
    untouched, then forces every spread to contain exactly ONE page.
    -----------------------------------------------------------
*/

#target indesign

(function () {

    if (app.documents.length === 0) {
        alert("Please open a document first.");
        return;
    }

    var srcDoc = app.activeDocument;

    // -----------------------------------------------------------
    // 1. Duplicate the document so we don't damage the original
    // -----------------------------------------------------------
    var srcPath = srcDoc.fullName;
    var newDoc;
    try {
        // Save a copy and reopen so we get a clean working file
        var tempFile = File(Folder.temp + "/" + srcDoc.name.replace(/\.indd$/i, "") + "_singlePages.indd");
        srcDoc.saveACopy(tempFile);
        newDoc = app.open(tempFile);
    } catch (e) {
        alert("Could not duplicate document: " + e.message);
        return;
    }

    // -----------------------------------------------------------
    // 2. Remember original settings, then disable facing pages
    //    and "Allow Document/Spread Shuffle".
    //    These must be off so InDesign lets us isolate each page
    //    onto its own spread.
    // -----------------------------------------------------------
    app.scriptPreferences.userInteractionLevel =
        UserInteractionLevels.NEVER_INTERACT;

    var origRulerOrigin = newDoc.viewPreferences.rulerOrigin;
    newDoc.viewPreferences.rulerOrigin = RulerOrigin.PAGE_ORIGIN;

    // Disable facing pages – preserves margin values
    if (newDoc.documentPreferences.facingPages) {
        newDoc.documentPreferences.facingPages = false;
    }

    // Allow shuffle so we can move pages between spreads
    newDoc.documentPreferences.allowPageShuffle = true;

    // -----------------------------------------------------------
    // 3. Process MASTER spreads – split any multi-page master
    //    spread into one-page master spreads while keeping the
    //    items in place.
    // -----------------------------------------------------------
    // (Master spreads can't be split via "allowPageShuffle"
    //  the same way; we set their pages-per-spread to 1.)
    for (var m = 0; m < newDoc.masterSpreads.length; m++) {
        var ms = newDoc.masterSpreads[m];
        // Reducing pagesPerSpread to 1 puts each master page on its own spread
        try {
            if (ms.pages.length > 1) {
                ms.pagesPerSpread = 1;
            }
        } catch (err) {
            // Some versions need explicit page splitting
        }
    }

    // -----------------------------------------------------------
    // 4. Process document SPREADS – ensure every spread has 1 page.
    //    We iterate from the END so indices stay valid as we move.
    // -----------------------------------------------------------
    var spreads = newDoc.spreads;
    for (var s = spreads.length - 1; s >= 0; s--) {
        var spread = spreads[s];

        // Keep moving extra pages off this spread until only 1 remains
        while (spread.pages.length > 1) {
            var lastPage = spread.pages[spread.pages.length - 1];

            // Remember the master applied to this page
            var appliedMaster = lastPage.appliedMaster;

            // Move the page so it becomes its own spread, right after
            // the current spread.
            lastPage.move(LocationOptions.AFTER, spread);

            // Re-apply master (move() preserves it, but we make sure)
            if (appliedMaster) {
                try { lastPage.appliedMaster = appliedMaster; } catch (e2) {}
            }
        }
    }

    // -----------------------------------------------------------
    // 5. Lock down: prevent automatic shuffling from re-pairing
    // -----------------------------------------------------------
    newDoc.documentPreferences.allowPageShuffle = false;

    // Restore ruler origin
    newDoc.viewPreferences.rulerOrigin = origRulerOrigin;

    app.scriptPreferences.userInteractionLevel =
        UserInteractionLevels.INTERACT_WITH_ALL;

    alert("Done!\n\nConverted document:\n" + newDoc.fullName.fsName +
          "\n\nPages: " + newDoc.pages.length +
          "\nSpreads: " + newDoc.spreads.length);

})();
```

### How it works

1. **Safe copy** – The script first duplicates the open document to your temp folder and opens that copy, so your original file stays untouched.
2. **Facing pages off** – Disables facing pages (margins are preserved as inside/outside become left/right).
3. **Master pages** – Sets every multi-page master spread to `pagesPerSpread = 1`, so each master page lives on its own spread.
4. **Document pages** – Walks each spread from the end backwards. While a spread holds more than one page, the trailing page is moved to a new spread of its own using `LocationOptions.AFTER`. The applied master (A-Master, B-Master, …) is re-asserted to guarantee the reference is kept.
5. **Shuffle locked** – `allowPageShuffle` is turned off so InDesign won't auto-pair pages again.

### Result
- One page per spread
- Original page size, margins, columns, and item coordinates intact
- Each page still references its original master (A, B, C…)
- Master spreads themselves are also flattened to single pages

Save the file as `SpreadsToSinglePages.jsx` in your InDesign **Scripts Panel** folder and double-click it to run.

